package mp4

import (
	"bytes"
	"encoding/binary"
)

// FixtureSpec controls the deterministic in-memory MP4 fixture builder.
type FixtureSpec struct {
	TrackID            uint32
	Timescale          uint32
	SampleCount        int
	SampleSize         int
	SyncNumbers        []uint32
	CompositionOffsets []int32
	BadChunkOffset     bool
	MinorVersion       uint32
}

// BuiltFixture contains generated bytes and patch locations useful to tests.
type BuiltFixture struct {
	Data             []byte
	MoovOffset       int
	STCOBoxOffset    int
	STCOEntriesStart int
	ChunkDataStart   int
	ChunkOffsets     []int
}

func be16(v uint16) []byte {
	b := make([]byte, 2)
	binary.BigEndian.PutUint16(b, v)
	return b
}

func be32(v uint32) []byte {
	b := make([]byte, 4)
	binary.BigEndian.PutUint32(b, v)
	return b
}

func box(typ string, payload []byte) []byte {
	var b bytes.Buffer
	b.Write(be32(uint32(8 + len(payload))))
	b.WriteString(typ)
	b.Write(payload)
	return b.Bytes()
}

func fullBox(typ string, version byte, flags uint32, payload []byte) []byte {
	vf := []byte{version, byte(flags >> 16), byte(flags >> 8), byte(flags)}
	return box(typ, append(vf, payload...))
}

func ftypBox(minor uint32) []byte {
	var p bytes.Buffer
	p.WriteString("isom")
	p.Write(be32(minor))
	p.WriteString("isom")
	p.WriteString("iso2")
	p.WriteString("mp41")
	return box("ftyp", p.Bytes())
}

func mvhdBox(timescale, duration uint32) []byte {
	var p bytes.Buffer
	p.Write(be32(0)) // creation
	p.Write(be32(0)) // modification
	p.Write(be32(timescale))
	p.Write(be32(duration))
	p.Write(be32(0x00010000)) // rate 1.0
	p.Write(be16(0x0100))     // volume
	p.Write(make([]byte, 10))
	matrix := []uint32{0x00010000, 0, 0, 0, 0x00010000, 0, 0, 0, 0x40000000}
	for _, m := range matrix {
		p.Write(be32(m))
	}
	p.Write(make([]byte, 24)) // pre-defined
	p.Write(be32(2))          // next track id
	return fullBox("mvhd", 0, 0, p.Bytes())
}

func tkhdBox(trackID, duration uint32) []byte {
	var p bytes.Buffer
	p.Write(be32(0))
	p.Write(be32(0))
	p.Write(be32(trackID))
	p.Write(be32(0))
	p.Write(be32(duration))
	p.Write(make([]byte, 8))
	p.Write(be16(0)) // layer
	p.Write(be16(0)) // alternate group
	p.Write(be16(0)) // volume
	p.Write(be16(0)) // reserved
	matrix := []uint32{0x00010000, 0, 0, 0, 0x00010000, 0, 0, 0, 0x40000000}
	for _, m := range matrix {
		p.Write(be32(m))
	}
	p.Write(be32(16 << 16)) // width 16.0
	p.Write(be32(16 << 16)) // height 16.0
	return fullBox("tkhd", 0, 0x000003, p.Bytes())
}

func mdhdBox(timescale, duration uint32) []byte {
	var p bytes.Buffer
	p.Write(be32(0))
	p.Write(be32(0))
	p.Write(be32(timescale))
	p.Write(be32(duration))
	p.Write(be16(0x55c4)) // und-ish language
	p.Write(be16(0))
	return fullBox("mdhd", 0, 0, p.Bytes())
}

func hdlrBox() []byte {
	var p bytes.Buffer
	p.Write(be32(0))
	p.WriteString("vide")
	p.Write(make([]byte, 12))
	p.WriteString("VideoHandler\x00")
	return fullBox("hdlr", 0, 0, p.Bytes())
}

func videoSampleEntry() []byte {
	var p bytes.Buffer
	p.Write(make([]byte, 6))
	p.Write(be16(1)) // data reference index
	p.Write(be16(0))
	p.Write(be16(0))
	p.Write(make([]byte, 12))
	p.Write(be16(16)) // width
	p.Write(be16(16)) // height
	p.Write(be32(0x00480000))
	p.Write(be32(0x00480000))
	p.Write(be32(0))
	p.Write(be16(1)) // frame count
	name := make([]byte, 32)
	copy(name, []byte{0, 'd', 'e', 'm', 'o'})
	p.Write(name)
	p.Write(be16(0x0018))
	p.Write(be16(0xffff))
	return box("mp4v", p.Bytes())
}

func stsdBox() []byte {
	var p bytes.Buffer
	p.Write(be32(1))
	p.Write(videoSampleEntry())
	return fullBox("stsd", 0, 0, p.Bytes())
}

func sttsBox(count int, delta uint32) []byte {
	var p bytes.Buffer
	p.Write(be32(1))
	p.Write(be32(uint32(count)))
	p.Write(be32(delta))
	return fullBox("stts", 0, 0, p.Bytes())
}

func cttsBox(offsets []int32) []byte {
	if len(offsets) == 0 {
		return nil
	}
	var p bytes.Buffer
	p.Write(be32(uint32(len(offsets))))
	for _, o := range offsets {
		p.Write(be32(1))
		p.Write(be32(uint32(o)))
	}
	return fullBox("ctts", 1, 0, p.Bytes())
}

func stscBox() []byte {
	var p bytes.Buffer
	p.Write(be32(1))
	p.Write(be32(1))
	p.Write(be32(1))
	p.Write(be32(1))
	return fullBox("stsc", 0, 0, p.Bytes())
}

func stszBox(sizes []uint32) []byte {
	var p bytes.Buffer
	p.Write(be32(0))
	p.Write(be32(uint32(len(sizes))))
	for _, sz := range sizes {
		p.Write(be32(sz))
	}
	return fullBox("stsz", 0, 0, p.Bytes())
}

func stssBox(numbers []uint32) []byte {
	if len(numbers) == 0 {
		return nil
	}
	var p bytes.Buffer
	p.Write(be32(uint32(len(numbers))))
	for _, n := range numbers {
		p.Write(be32(n))
	}
	return fullBox("stss", 0, 0, p.Bytes())
}

func stcoBox(offsets []uint32) []byte {
	var p bytes.Buffer
	p.Write(be32(uint32(len(offsets))))
	for _, o := range offsets {
		p.Write(be32(o))
	}
	return fullBox("stco", 0, 0, p.Bytes())
}
